Perfect! I have extracted the exact implementations. Here's the complete information:

## Function Implementations

### 1. parse-vessel/route.ts
```typescript
function extractNum(v: any): number | null {
  if (v == null) return null;
  if (typeof v === 'number') return isNaN(v) ? null : v;
  if (typeof v === 'string') { const n = parseFloat(v); return isNaN(n) ? null : n; }
  if (typeof v === 'object' && 'value' in v) return extractNum(v.value);
  return null;
}

function toConfidence<T>(field: any): ConfidenceField<T> | null {
  if (!field) return null;
  if (typeof field === 'object' && 'value' in field) {
    return {
      value: field.value,
      confidence: field.confidence || 'confirmed',
      sourceText: field.source_text || undefined,
    };
  }
  return { value: field as T, confidence: 'confirmed' };
}
```

### 2. parse-recap/route.ts
```typescript
function extractNum(v: any): number | null {  if (v == null) return null;  if (typeof v === "number") return v;  if (typeof v === "string") { const n = parseFloat(v); return isNaN(n) ? null : n; }  if (typeof v === "object" && "value" in v) return extractNum(v.value);  return null;}

function toConfidence<T>(field: any): ConfidenceField<T> | null {
  if (!field) return null;
  if (typeof field === 'object' && 'value' in field) {
    return {
      value: field.value,
      confidence: field.confidence || 'confirmed',
      sourceText: field.source_text || undefined,
    };
  }
  return { value: field as T, confidence: 'confirmed' };
}
```

**Note:** The `extractNum` in parse-recap is on a single line and has a subtle difference - it returns `v` directly for numbers instead of checking `isNaN(v)`.

### 3. parse-cargo/route.ts
Only contains `toConfidence` (no `extractNum` function):
```typescript
function toConfidence<T>(field: any): ConfidenceField<T> | null {
  if (!field) return null;
  if (typeof field === 'object' && 'value' in field) {
    return {
      value: field.value,
      confidence: field.confidence || 'confirmed',
      sourceText: field.source_text || undefined,
    };
  }
  return { value: field as T, confidence: 'confirmed' };
}
```

### 4. Type Definitions (types.ts)
```typescript
export type ConfidenceLevel = 'confirmed' | 'interpreted' | 'uncertain';

export interface ConfidenceField<T> {
  value: T;
  confidence: ConfidenceLevel;
  sourceText?: string;
}

export function cfValue<T>(field: ConfidenceField<T> | null | undefined): T | null {
  return field?.value ?? null;
}
```

## Key Differences Found

1. **extractNum in parse-vessel**: Checks `isNaN(v)` for number types
